def square(x: int) -> int:
    """Return the square of x."""
    return x * x


def squares(xs: list[int]) -> list[int]:
    """Square every element in parallel using a thread pool."""
    from concurrent.futures import ThreadPoolExecutor

    with ThreadPoolExecutor() as executor:
        return list(executor.map(square, xs))


def test_square() -> None:
    assert square(0) == 0
    assert square(-3) == 9
    assert square(5) == 25


def test_squares_empty() -> None:
    assert squares([]) == []


def test_squares_single() -> None:
    assert squares([4]) == [16]
    assert squares([-5]) == [25]


def test_squares_preserves_order() -> None:
    assert squares([3, 1, 4, 1, 5, 9, 2, 6]) == [9, 1, 16, 1, 25, 81, 4, 36]


def test_squares_mixed_values() -> None:
    assert squares([-3, -1, 0, 1, 2]) == [9, 1, 0, 1, 4]


def test_squares_large_input() -> None:
    xs = list(range(-50, 50))
    assert squares(xs) == [x * x for x in xs]

